# Let me print all 46 sequences to see what we have
target = "{TARGET}"
with open(target, 'rb') as f:
    data = f.read()

printable_sequences = []
current = b''
for i, b in enumerate(data):
    if 32 <= b < 127:
        current += bytes([b])
    else:
        if len(current) >= 10:
            printable_sequences.append((i - len(current), current.decode('ascii')))
        current = b''

print("All printable sequences (10+ chars):")
for pos, seq in printable_sequences:
    print(f"Offset {pos}: {seq}")
